solution:
static int secondLargest(int[] xs) {
    int largest = xs[0];
    int second = 0;
    boolean haveSecond = false;

    for (int x : xs) {
        if (x > largest) {
            second = largest;          // the old maximum slides down
            haveSecond = true;
            largest = x;
        } else if (x != largest && (!haveSecond || x > second)) {
            second = x;
            haveSecond = true;
        }
    }
    return second;
}
